        const slider = document.getElementById("dateSlider");
        slider.max = gaugeData.length - 1;
        const dateText = document.getElementById("dateText");
        const dateInput = document.getElementById("dateInput");
        const jumpButton = document.getElementById("jumpButton");
        const dateMsg = document.getElementById("dateMsg");

        const tabButtons = document.querySelectorAll(".tab-button");
        const pages = document.querySelectorAll(".page");

        tabButtons.forEach(function(button) {
            button.addEventListener("click", function() {
                const targetPage = this.getAttribute("data-page");

                tabButtons.forEach(function(btn) {
                    btn.classList.remove("active");
                });

                pages.forEach(function(page) {
                    page.classList.remove("active");
                });

                this.classList.add("active");
                document.getElementById(targetPage).classList.add("active");

                if (targetPage === "page-1") {
                    setTimeout(function() {
                        Plotly.Plots.resize("top-chart");
                        Plotly.Plots.resize("signal-backtest-chart");
                        Plotly.Plots.resize("gauge-chart");
                    }, 80);
                }
            });
        });

        function updateByIndex(idx) {
            idx = Math.max(0, Math.min(idx, gaugeData.length - 1));

            const gaugeItem = gaugeData[idx];
            const tableItem = tableData[idx];
            const dateStr = gaugeItem.date;

            slider.value = idx;
            dateText.innerText = dateStr;
            dateInput.value = dateStr;
            dateMsg.innerText = "";

            document.getElementById("percentile-table").innerHTML = tableItem.html;

            Plotly.restyle(
                "gauge-chart",
                {"value": gaugeItem.values},
                [0, 1, 2, 3, 4, 5, 6]
            );
        }

        function findNearestDateIndex(targetDateStr) {
            const target = new Date(targetDateStr);

            if (isNaN(target.getTime())) {
                return null;
            }

            let nearestIdx = 0;

            for (let i = 0; i < gaugeData.length; i++) {
                const d = new Date(gaugeData[i].date);

                if (d <= target) {
                    nearestIdx = i;
                } else {
                    break;
                }
            }

            return nearestIdx;
        }

        slider.addEventListener("input", function() {
            updateByIndex(parseInt(this.value));
        });

        jumpButton.addEventListener("click", function() {
            const inputDate = dateInput.value.trim();
            const idx = findNearestDateIndex(inputDate);

            if (idx === null) {
                dateMsg.innerHTML = "<span style='color:#C00000'>日期格式不正确，请输入 YYYY-MM-DD</span>";
                return;
            }

            const selectedDate = gaugeData[idx].date;
            updateByIndex(idx);

            if (selectedDate !== inputDate) {
                dateMsg.innerHTML = "输入日期非交易日或无数据，已跳转到最近可用日期：<b>" + selectedDate + "</b>";
            } else {
                dateMsg.innerHTML = "";
            }
        });

        dateInput.addEventListener("keydown", function(event) {
            if (event.key === "Enter") {
                jumpButton.click();
            }
        });

        updateByIndex(2542);

        function classifySignalValue(value) {
            if (value >= 80) {
                return {
                    label: "偏热",
                    className: "tag tag-hot"
                };
            }

            if (value <= 30) {
                return {
                    label: "偏冷",
                    className: "tag tag-cool"
                };
            }

            return {
                label: "中性",
                className: "tag tag-mid"
            };
        }

        function signalNote(name, signal) {
            const notes = {
                "融资资金": {
                    "偏热": "场内资金活跃度处于高位，短期交易热度较强。",
                    "中性": "融资资金处于中性区间，杠杆资金情绪未明显偏离。",
                    "偏冷": "融资资金处于低位，场内资金风险偏好偏弱。"
                },
                "外资资金成交额": {
                    "偏热": "外资成交参与度偏高，对市场流动性形成支撑。",
                    "中性": "外资成交活跃度处于中性区间，方向信号不极端。",
                    "偏冷": "外资成交参与度偏低，外部资金动能较弱。"
                },
                "行业 ETF 净申购": {
                    "偏热": "行业方向配置强度较高，结构性资金热度上升。",
                    "中性": "行业方向配置强度适中，结构分化需要继续观察。",
                    "偏冷": "行业方向配置强度仍在低位，结构性分化明显。"
                },
                "沪深300ETF隐含波动率": {
                    "偏热": "期权隐波偏高，市场预期波动加大。",
                    "中性": "期权隐波处于中性区间，预期波动未进入极端。",
                    "偏冷": "期权隐波处于低位，市场预期波动较弱。"
                },
                "持仓 PCR": {
                    "偏热": "期权持仓结构偏热，需观察是否形成一致预期。",
                    "中性": "投资者结构变化尚未形成单边信号。",
                    "偏冷": "期权持仓结构偏冷，防御情绪相对更强。"
                },
                "MACD": {
                    "偏热": "趋势动能较强，但需观察高位钝化风险。",
                    "中性": "趋势动能处于中性区间，方向信号不极端。",
                    "偏冷": "趋势动能偏弱，市场仍需等待修复信号。"
                },
                "乖离率": {
                    "偏热": "指数偏离均线程度偏高，需留意短期波动。",
                    "中性": "指数偏离均线程度适中，尚未进入极端区间。",
                    "偏冷": "指数偏离均线程度偏低，市场情绪较弱。"
                }
            };

            return notes[name] && notes[name][signal] ? notes[name][signal] : "";
        }

        function updateSignalMatrix(idx) {
            const rows = document.querySelectorAll(".signal-table tbody tr");
            if (!rows.length || !gaugeData[idx]) {
                return;
            }

            const names = [
                "融资资金",
                "外资资金成交额",
                "行业 ETF 净申购",
                "沪深300ETF隐含波动率",
                "持仓 PCR",
                "MACD",
                "乖离率"
            ];
            const values = gaugeData[idx].values || [];

            rows.forEach(function(row, rowIndex) {
                const value = Number(values[rowIndex]);
                if (!Number.isFinite(value)) {
                    return;
                }

                const cells = row.querySelectorAll("td");
                const valueCell = cells[1];
                const statusTag = row.querySelector(".tag");
                const noteCell = cells[cells.length - 1];
                const signal = classifySignalValue(value);

                if (valueCell) {
                    valueCell.textContent = Math.round(value) + "%";
                }

                if (statusTag) {
                    statusTag.textContent = signal.label;
                    statusTag.className = signal.className;
                }

                if (noteCell) {
                    noteCell.textContent = signalNote(names[rowIndex], signal.label);
                }
            });
        }

        updateSignalMatrix(2542);

        slider.addEventListener("input", function() {
            updateSignalMatrix(Number(slider.value));
        });

        jumpButton.addEventListener("click", function() {
            window.setTimeout(function() {
                updateSignalMatrix(Number(slider.value));
            }, 0);
        });

(function () {
  function fitChartWidth(id, maxWidth) {
    var el = document.getElementById(id);
    if (!el || !window.Plotly) return;

    var frame = el.closest('.chart-frame');
    var frameWidth = frame ? frame.clientWidth - 20 : el.clientWidth;
    var width = Math.max(320, frameWidth);

    if (maxWidth) {
      width = Math.min(width, maxWidth);
    }

    el.style.width = width + 'px';
    window.Plotly.relayout(el, { width: width });
  }

  function resizeCharts() {
    if (!window.Plotly) return;
    fitChartWidth('top-chart');
    fitChartWidth('signal-backtest-chart');
    fitChartWidth('gauge-chart', 1380);
  }
  window.addEventListener('load', resizeCharts);
  window.addEventListener('resize', resizeCharts);
  document.querySelectorAll('.tab-button').forEach(function (button) {
    button.addEventListener('click', function () { setTimeout(resizeCharts, 80); });
  });
})();

(function () {
  function arrangeMainDashboard() {
    var signals = document.getElementById('signals');
    var percentile = document.getElementById('percentile');
    var dateTools = document.querySelector('.date-tools');
    var dateMessage = document.getElementById('dateMsg');

    if (signals && dateTools && !signals.contains(dateTools)) {
      var tableWrap = signals.querySelector('.table-scroll');
      signals.insertBefore(dateTools, tableWrap);

      if (dateMessage) {
        signals.insertBefore(dateMessage, tableWrap);
      }
    }

    var titles = [
      { selector: '#charts article:nth-child(1) .module-header h2', text: '市场情绪与万得全A走势' },
      { selector: '#signals .module-header h2', text: '核心指标信号矩阵' },
      { selector: '#percentile .module-header h2', text: '历史分位查询' },
      { selector: '#charts article:nth-child(3) .module-header h2', text: '分项情绪仪表盘' },
      { selector: '#charts article:nth-child(2) .module-header h2', text: '高热 / 低迷信号回测' }
    ];

    titles.forEach(function (item) {
      var el = document.querySelector(item.selector);
      if (el) {
        el.textContent = item.text;
      }
    });

  }

  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', arrangeMainDashboard);
  } else {
    arrangeMainDashboard();
  }
})();
